def credit_text(metadata):
    values = {
        k: metadata.get(k) or ("この音声モデルの利用条件を確認してください。" if k == "credit" else "UNKNOWN")
        for k in ("name", "path", "source", "license", "credit")
    }
    return (
        "SubVoice 音声生成情報\n\nTTS Engine: Style-Bert-VITS2\nVoice Model: {name}\nModel Path: {path}\nSource: {source}\nLicense: {license}\nCredit:\n{credit}\n\nGenerated by: SubVoice 字幕読み上げツール\n"
    ).format(**values)
